require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/totp_helper.php';require_once __DIR__.'/../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../index.php');
$adminId=(int)$_SESSION['admin_id'];$result=pg_query_params($conn,'SELECT username,full_name,password_hash,totp_secret,totp_enabled,backup_codes FROM admins WHERE id=$1',[$adminId]);if(!$result||pg_num_rows($result)!==1)die('Unable to load administrator account.');$admin=pg_fetch_assoc($result);$error='';
try{$totpSecret=decrypt_sensitive_value($admin['totp_secret']??'');if($totpSecret===''){$totpSecret=TOTP::generateSecret();if(!pg_query_params($conn,'UPDATE admins SET totp_secret=$1 WHERE id=$2',[encrypt_sensitive_value($totpSecret),$adminId]))throw new RuntimeException('Unable to initialize two-factor authentication.');}elseif(!str_starts_with((string)$admin['totp_secret'],'enc:v1:')){pg_query_params($conn,'UPDATE admins SET totp_secret=$1 WHERE id=$2',[encrypt_sensitive_value($totpSecret),$adminId]);}}catch(Throwable $e){$totpSecret='';$error='Two-factor authentication setup is unavailable. Check the APP_KEY configuration.';error_log($e->getMessage());}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired. Refresh the page and try again.';
 elseif(isset($_POST['enable_2fa'])&&$totpSecret!==''){$passwordOk=verify_admin_password($conn,$adminId,$_POST['admin_password']??'');$counter=TOTP::verifyCodeAndGetCounter($totpSecret,trim($_POST['totp_code']??''));if($passwordOk&&$counter!==false){$claim=claim_admin_totp_counter($conn,$adminId,$counter);if($claim===true){$codes=TOTP::generateBackupCodes();$hashes=TOTP::hashBackupCodes($codes);if(pg_query_params($conn,'UPDATE admins SET totp_enabled=TRUE,backup_codes=$1 WHERE id=$2',[$hashes,$adminId])){session_regenerate_id(true);audit_log($conn,'admin_2fa_enabled','admin',$adminId);$_SESSION['flash_backup_codes']=$codes;redirect('profile.php?enabled=1');}$error='Unable to enable two-factor authentication.';}else $error=$claim===false?'This authenticator code was already used. Wait for a new code.':'Unable to validate the authenticator code.';}else $error='Enter your correct password and a valid 6-digit authenticator code.';}
 elseif(isset($_POST['disable_2fa'])){$passwordOk=verify_admin_password($conn,$adminId,$_POST['admin_password']??'');$counter=$totpSecret!==''?TOTP::verifyCodeAndGetCounter($totpSecret,trim($_POST['totp_code']??'')):false;if($passwordOk&&$counter!==false){$claim=claim_admin_totp_counter($conn,$adminId,$counter);if($claim===true&&pg_query_params($conn,'UPDATE admins SET totp_enabled=FALSE,totp_secret=NULL,backup_codes=NULL WHERE id=$1',[$adminId])){session_regenerate_id(true);audit_log($conn,'admin_2fa_disabled','admin',$adminId);$_SESSION['security_flash']='Two-factor authentication was disabled.';redirect('profile.php');}$error=$claim===false?'This authenticator code was already used. Wait for a new code.':'Unable to disable two-factor authentication.';}else $error='Enter your correct password and current authenticator code.';}
}
$backupCodes=$_SESSION['flash_backup_codes']??[];unset($_SESSION['flash_backup_codes']);$flash=$_SESSION['security_flash']??'';unset($_SESSION['security_flash']);$enabled=$admin['totp_enabled']==='t'||$admin['totp_enabled']===true;admin_page_start('Account Security','security');?>
<div class="welcome-banner"><div><h2><i class="fas fa-user-lock"></i> Account Security</h2><p>Manage your two-factor authentication settings and backup codes.</p></div><div class="banner-icon"><i class="fas fa-shield-halved"></i></div></div>
<?php if($error):?><div class="alert error"><i class="fas fa-triangle-exclamation"></i> <?=h($error)?></div><?php elseif($flash):?><div class="alert"><?=h($flash)?></div><?php endif;?>
<?php if($backupCodes):?><div class="backup-code-alert"><h3><i class="fas fa-key"></i> Save these backup codes now</h3><p>Each code can be used once if your authenticator is unavailable. They will not be displayed again.</p><div class="backup-code-grid"><?php foreach($backupCodes as $code):?><code><?=h($code)?></code><?php endforeach;?></div><button class="btn secondary" onclick="window.print()"><i class="fas fa-print"></i> Print codes</button></div><?php endif;?>
<div class="dashboard-grid security-grid"><div class="panel"><div class="panel-header"><h3><i class="fas fa-mobile-screen-button"></i> Two-Factor Authentication (2FA)</h3><span class="badge <?=$enabled?'badge-active':'badge-draft'?>"><?=$enabled?'Enabled':'Not enabled'?></span></div><div class="panel-body">
<?php if(!$enabled):?><p>Two-factor authentication adds an authenticator code after your password during administrator sign-in.</p><p class="help">Add this account manually in Google Authenticator, Microsoft Authenticator, Authy, or another TOTP application.</p><div class="security-key"><div><span>Account</span><strong><?=h($admin['username'])?></strong></div><div><span>Setup key</span><code><?=h($totpSecret)?></code></div><div><span>Type</span><strong>Time based</strong></div></div><form method="post" class="form-grid" autocomplete="off"><?=csrf_field()?><div class="field full"><label>Current administrator password</label><input type="password" name="admin_password" required autocomplete="current-password"></div><div class="field full"><label>6-digit authenticator code</label><input type="text" name="totp_code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code" placeholder="000000"></div><div class="field full"><button class="btn" name="enable_2fa"><i class="fas fa-shield-halved"></i> Verify and enable 2FA</button></div></form>
<?php else:?><div class="status-alert ongoing"><i class="fas fa-circle-check"></i><div><strong>Two-factor authentication is enabled.</strong><br>Your account requires an authenticator or unused backup code at sign-in.</div></div><p class="help">Your current password and a fresh authenticator code are required to disable this protection.</p><form method="post" class="form-grid" autocomplete="off" data-confirm-title="Disable two-factor authentication?" data-confirm="This will reduce the security of your administrator account." data-confirm-button="Yes, disable 2FA"><?=csrf_field()?><div class="field full"><label>Current administrator password</label><input type="password" name="admin_password" required autocomplete="current-password"></div><div class="field full"><label>Current 6-digit code</label><input type="text" name="totp_code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code" placeholder="000000"></div><div class="field full"><button class="btn danger" name="disable_2fa"><i class="fas fa-shield"></i> Disable 2FA</button></div></form><?php endif;?></div></div>
